use serde_json::{json,Value};
use ss_core::{java_runtime::Rc,cn::wps::moss::app::{KmoBook::KmoBook,KmoBookApi::KmoBookApi}};
fn record(book:&Rc<KmoBook>,step:&str)->Value{let mut sheets=vec![];for i in 0..2{let sheet=book.sheetAt(i);let s=sheet.borrow();let mut cells=vec![];for r in [70,72]{cells.push(json!({"row":r,"bits":format!("{:016x}",s.getCellNumericValue(r,31).to_bits()),"formulaType":s.getCellData(r,31).formulaType}));}sheets.push(cells);}json!({"step":step,"sheets":sheets,"dirty":book.isDirty(),"autoSaveInterrupted":book.isInterruptAutoSave(),"canUndo":book.canUndo(),"canRedo":book.canRedo(),"active":book.getActiveSheet().borrow().getSheetIndex(),"started":book.transaction().isTransStarted()})}
fn calculate(book:&Rc<KmoBook>){let cc=book.getCalculationChain().unwrap();for i in 0..2{cc.markRecalculation__area(i,70,72,31,31,true);}cc.synCalculate();let gaps=cc.calcChain.unportedEvaluationBranches();assert!(gaps.iter().all(|(_,r,c,_)|*r!=72||*c!=31),"accepted local-sheet formula reached an unported branch: {gaps:?}");}
fn settle(book:&Rc<KmoBook>){std::thread::sleep(std::time::Duration::from_millis(200));book.getCalculationChain().unwrap().synCalculate();}
fn value(v:&ss_core::cn::wps::et::ss::formula::eval::ValueRef)->Value{
    use ss_core::cn::wps::et::ss::formula::eval::{NumberEval::NumberEval,ErrorEval::ErrorEval};
    if let Some(r)=v.as_ref_eval(){return json!({"kind":"ref","sheet":r.getSheetIndex(),"row":r.getRow(),"col":r.getColumn(),"inner":value(&r.getInnerValueEval().ok().unwrap().unwrap())});}
    if let Some(a)=v.as_area_eval(){let b=a.base();let mut values=vec![];for r in 0..b.getHeight(){for c in 0..b.getWidth(){values.push(value(&a.getRelativeValue(r,c).ok().unwrap()));}}return json!({"kind":"area","sheet":a.getSheetIndex(),"box":[b.getFirstRow(),b.getLastRow(),b.getFirstColumn(),b.getLastColumn()],"rav":b.getRAV(),"values":values});}
    if let Some(n)=v.as_any().downcast_ref::<NumberEval>(){return json!({"kind":"number","bits":format!("{:016x}",n.getNumberValue().to_bits())});}
    if let Some(e)=v.as_any().downcast_ref::<ErrorEval>(){return json!({"kind":"error","code":e.getErrorCode()});}
    panic!("unexpected original reference observation")
}
fn references(book:&Rc<KmoBook>,expected:&Value)->Value{
    use ss_core::{org::apache::poi::ss::SpreadsheetVersion::SpreadsheetVersion,cn::wps::{moss::engine::eval::EvaluationWorkbook::EvaluationWorkbook,et::ss::{interfaces::IEvalWorkbook::IEvalWorkbook,formula::{ptg::Ptg::Ptg,evaluator::{EvaluationContext::EvaluationContext,WorkbookEvaluator::WorkbookEvaluator,WorkbookBytesEvaluator::WorkbookBytesEvaluator}}}}};
    for s in 0..2{for r in 10..13{for c in 10..13{book.sheetAt(s).borrow().setCellNumericValue(r,c,(s*1000+r*10+c)as f64);}}}let mut indices=vec![];for s in [0,1,-2,-1]{indices.push(book.getLinkTable().borrow_mut().checkNullSupBookExternSheet(s));}indices.extend([-1,32767]);let mut rows=vec![];
    for expected in expected.as_array().unwrap(){let input=&expected["input"];let version=if input["version"]==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007};book.setSpreadsheetVersion(version);let text=input["hex"].as_str().unwrap();let bytes:Vec<_>=(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).unwrap()).collect();assert_eq!(i16::from_le_bytes([bytes[1],bytes[2]])as i32,indices[input["which"].as_u64().unwrap()as usize]);let ew:Rc<dyn IEvalWorkbook>=Rc::new(EvaluationWorkbook::EvaluationWorkbook(book));let we=Rc::new(WorkbookEvaluator::WorkbookEvaluator(ew.clone()));let mut ec=EvaluationContext::EvaluationContext(we.clone(),ew,input["sheet"].as_i64().unwrap()as i32,1,1,input["shared"].as_bool().unwrap());let stack=WorkbookBytesEvaluator::WorkbookBytesEvaluator(we.clone()).evaluateFormula(&mut ec,&bytes,bytes.len()as i32).ok().expect("ported original 3D bytes branch");let from_bytes=value(stack.front().unwrap());let ptgs=Ptg::readTokens(bytes.len()as i32,&bytes,version);let from_ptg=value(&we.getEvalForOperandPtg(&ptgs[0],&mut ec).ok().expect("ported original 3D Ptg branch"));let row=json!({"input":input,"bytes":from_bytes,"ptg":from_ptg});assert_eq!(row,*expected);rows.push(row);
    }book.setSpreadsheetVersion(SpreadsheetVersion::EXCEL2007);json!(rows)
}
#[test]
fn original_android_multi_sheet_dependency_undo_redo_and_branch(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/dependencies-r0b31");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/sparse-multisheet.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let a=book.sheetAt(0);let b=book.sheetAt(1);let a=a.borrow();let b=b.borrow();a.setCellNumericValue(70,31,5.0);b.setCellNumericValue(70,31,9.0);a.initCellFormula(72,31,&format!("'{}'!AF71+AF71",b.name().replace('\'',"''")),-1,15).unwrap();b.initCellFormula(72,31,&format!("'{}'!AF71*2",a.name().replace('\'',"''")),-1,15).unwrap();let cc=book.getCalculationChain().unwrap();cc.registerFormula(0,72,31);cc.registerFormula(1,72,31);calculate(&book);book.transaction().reset();book.setDirty(false);let mut out=vec![record(&book,"initial")];
    book.transaction().start();a.setCellNumericValue(70,31,10.0);b.setCellNumericValue(70,31,20.0);book.transaction().start();a.setCellNumericValue(70,31,12.0);book.transaction().commit();calculate(&book);out.push(record(&book,"innerCommit"));book.transaction().commit();out.push(record(&book,"outerCommit"));
    book.undo();settle(&book);out.push(record(&book,"undo"));book.redo();settle(&book);out.push(record(&book,"redo"));book.undo();settle(&book);out.push(record(&book,"undoAgain"));
    book.activateSheet(1);book.transaction().start();b.setCellNumericValue(70,31,33.0);book.transaction().commit();calculate(&book);out.push(record(&book,"branch"));book.redo();settle(&book);out.push(record(&book,"redoAfterBranch"));book.undo();settle(&book);out.push(record(&book,"undoBranch"));book.redo();settle(&book);out.push(record(&book,"redoBranch"));let actual=json!(out);std::fs::write(p.join("rust-transactions.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();assert_eq!(actual,java["transactions"]);let refs=references(&book,&java["references"]);std::fs::write(p.join("rust-references.json"),serde_json::to_vec_pretty(&refs).unwrap()).unwrap();
}
